begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b1100000-0000-4000-8000-000000000001','authenticated','authenticated','purchase-a@example.test','',now(),'{}','{"name":"Purchase QA A","company_name":"Purchase QA A"}',now(),now()),
('b1100000-0000-4000-8000-000000000002','authenticated','authenticated','purchase-b@example.test','',now(),'{}','{"name":"Purchase QA B","company_name":"Purchase QA B"}',now(),now()),
('b1100000-0000-4000-8000-000000000003','authenticated','authenticated','purchase-peer@example.test','',now(),'{}','{"name":"Purchase QA Peer","company_name":"Purchase QA Peer"}',now(),now());
update public.profiles set company_id=(select company_id from public.profiles where auth_user_id='b1100000-0000-4000-8000-000000000001') where auth_user_id='b1100000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"b1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('purchase.company',private.current_company_id(),true);
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('purchase-qa-material',private.current_company_id(),'QA material','unidade',9,20,true,10,5),('purchase-qa-service',private.current_company_id(),'QA serviço','unidade',1,2,false,0,0);
create function pg_temp.po(patch jsonb default '{}') returns jsonb language sql as $$select jsonb_build_object('supplier_id',current_setting('purchase.supplier'),'ordered_date',current_date,'expected_date',current_date+2,'payment_terms','2 parcelas QA','discount',5,'freight',10,'expenses',5,'items',jsonb_build_array(jsonb_build_object('product_id','purchase-qa-material','description','Snapshot material','unit','unidade','quantity',10,'unit_price',10),jsonb_build_object('product_id','purchase-qa-service','description','Snapshot serviço','unit','unidade','quantity',2,'unit_price',20)),'installments',jsonb_build_array(jsonb_build_object('due_date',current_date+10,'amount',75),jsonb_build_object('due_date',current_date+20,'amount',75)))||patch$$;
create function pg_temp.order_action(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.purchase_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at) from public.purchase_orders where id=current_setting('purchase.order')::uuid)||patch)$$;
grant execute on function pg_temp.po(jsonb),pg_temp.order_action(text,jsonb) to authenticated;
set local role authenticated;
select set_config('purchase.supplier',(public.purchase_command(gen_random_uuid(),'supplier_save','{"name":"Fornecedor QA A","person_type":"PJ","document":"12345678000195","contact_name":"Contato QA","contacts":[{"name":"Compras","email":"qa@example.test"}],"address":{"city":"Recife","state":"PE"}}')#>>'{supplier,id}'),true);
select is((select count(*)::int from public.suppliers),1,'supplier canonical registry');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save','{"name":"fornecedor QA A"}')$$,'%Já existe fornecedor%','duplicate name refused');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save','{"name":"Outro fornecedor","document":"12345678000195"}')$$,'%duplicate key%','tenant document unique');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save','{"name":"Documento inválido","document":"x"}')$$,'%Documento deve%','invalid document refused');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'supplier_save',(select to_jsonb(s)||'{"notes":"Editado QA"}'::jsonb from public.suppliers s where id=current_setting('purchase.supplier')))$$,'supplier editable with concurrency token');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save',jsonb_build_object('id',current_setting('purchase.supplier'),'name','Desatualizado'))$$,'%Registro atualizado%','stale supplier refused');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'supplier_link',jsonb_build_object('supplier_id',current_setting('purchase.supplier'),'product_id','purchase-qa-material','unit','unidade','reference_price',8,'preferred',true,'lead_days',2,'minimum_quantity',5,'vendor_sku','FORN-1'))$$,'supplier canonical product link');
select is((select base_cost from public.products where id='purchase-qa-material'),9::numeric,'reference never changes canonical cost');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_link',jsonb_build_object('supplier_id',current_setting('purchase.supplier'),'product_id','purchase-qa-material','unit','kg'))$$,'%unidade canônica%','unit conversion never presumed');
select set_config('purchase.request',(public.purchase_command(gen_random_uuid(),'request_save',jsonb_build_object('reason','Reposição QA','items',pg_temp.po()->'items'))->>'id'),true);
select is((select status from public.purchase_requests where id=current_setting('purchase.request')::uuid),'draft','request starts draft');
select throws_like($$select public.purchase_command(gen_random_uuid(),'request_transition',(select to_jsonb(r)||'{"status":"approved"}'::jsonb from public.purchase_requests r where id=current_setting('purchase.request')::uuid))$$,'%Transição%','cannot approve draft');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'request_transition',(select to_jsonb(r)||'{"status":"requested"}'::jsonb from public.purchase_requests r where id=current_setting('purchase.request')::uuid))$$,'request submitted');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'request_transition',(select to_jsonb(r)||'{"status":"approved"}'::jsonb from public.purchase_requests r where id=current_setting('purchase.request')::uuid))$$,'request approved');
select set_config('purchase.order',(public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po(jsonb_build_object('request_id',current_setting('purchase.request'))))->>'id'),true);
select is((select status from public.purchase_requests where id=current_setting('purchase.request')::uuid),'converted','request converted once');
select is((select number from public.purchase_orders where id=current_setting('purchase.order')::uuid),1::bigint,'tenant transactional sequence');
select is((select total from public.purchase_orders where id=current_setting('purchase.order')::uuid),150::numeric,'server total freight expenses discount');
select is((select sum(acquisition_total) from public.purchase_order_items where order_id=current_setting('purchase.order')::uuid),150::numeric,'landed costs reconcile exactly');
select is((select count(*)::int from public.financial_transactions),0,'draft creates no payable and no payment');
select throws_like($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po('{"installments":[{"amount":1,"due_date":"2026-10-24"}]}'))$$,'%soma das parcelas%','installments must reconcile');
select throws_like($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po('{"discount":9999}'))$$,'%Total ou desconto%','negative total refused');
select throws_like($$select pg_temp.order_action('receive',jsonb_build_object('received_date',current_date,'items','[]'::jsonb))$$,'%não permitem recebimento%','draft receipt refused');
select lives_ok($$select pg_temp.order_action('order_transition','{"status":"issued"}')$$,'issue purchase');
select lives_ok($$select pg_temp.order_action('order_transition','{"status":"confirmed"}')$$,'confirm purchase');
select throws_like($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po((select jsonb_build_object('id',id,'updated_at',updated_at) from public.purchase_orders where id=current_setting('purchase.order')::uuid)))$$,'%Somente rascunho%','confirmed snapshot immutable');
select set_config('purchase.receipt_payload',(select jsonb_build_object('id',o.id,'updated_at',o.updated_at,'received_date',current_date,'notes','QA parcial','items',jsonb_build_array(jsonb_build_object('item_id',i.id,'quantity',4)))::text from public.purchase_orders o join public.purchase_order_items i on i.order_id=o.id where o.id=current_setting('purchase.order')::uuid and i.product_id='purchase-qa-material'),true);
select set_config('purchase.operation',gen_random_uuid()::text,true);
select set_config('purchase.receipt',(public.purchase_command(current_setting('purchase.operation')::uuid,'receive',current_setting('purchase.receipt_payload')::jsonb)->>'receipt_id'),true);
select is((select current_stock from public.products where id='purchase-qa-material'),14::numeric,'partial receipt stock once');
select is((select status from public.purchase_orders where id=current_setting('purchase.order')::uuid),'partially_received','partial status derived');
select lives_ok($$select public.purchase_command(current_setting('purchase.operation')::uuid,'receive',current_setting('purchase.receipt_payload')::jsonb)$$,'identical receipt retry succeeds despite old version');
select is((select current_stock from public.products where id='purchase-qa-material'),14::numeric,'retry does not double stock');
select is((select count(*)::int from public.stock_movements where product_id='purchase-qa-material'),1,'only canonical movement');
select throws_like($$select public.purchase_command(current_setting('purchase.operation')::uuid,'receive',current_setting('purchase.receipt_payload')::jsonb||'{"notes":"Alterado"}'::jsonb)$$,'%reutilizada%','operation ID payload reuse refused');
select throws_like($$select public.purchase_command(gen_random_uuid(),'receive',current_setting('purchase.receipt_payload')::jsonb)$$,'%atualizada por outra pessoa%','stale mutation refused');
select throws_like($$select pg_temp.order_action('receive',jsonb_build_object('received_date',current_date,'items',jsonb_build_array(jsonb_build_object('item_id',(select id from public.purchase_order_items where order_id=current_setting('purchase.order')::uuid and product_id='purchase-qa-material'),'quantity',7))))$$,'%Quantidade excede%','overreceipt refused');
select is((select current_stock from public.products where id='purchase-qa-material'),14::numeric,'failed receipt atomic rollback');
select lives_ok($$select pg_temp.order_action('receive',jsonb_build_object('received_date',current_date,'items',(select jsonb_agg(jsonb_build_object('item_id',id,'quantity',case when product_id='purchase-qa-material' then 6 else 2 end)) from public.purchase_order_items where order_id=current_setting('purchase.order')::uuid)))$$,'remaining material and service received');
select is((select status from public.purchase_orders where id=current_setting('purchase.order')::uuid),'received','full status derived');
select is((select current_stock from public.products where id='purchase-qa-material'),20::numeric,'full stock');
select is((select current_stock from public.products where id='purchase-qa-service'),0::numeric,'service does not create stock');
select is((select base_cost from public.products where id='purchase-qa-material'),9::numeric,'acquisition never rewrites cost');
select is((select supplier_snapshot->>'name' from public.purchase_orders where id=current_setting('purchase.order')::uuid),'Fornecedor QA A','supplier snapshot preserved');
select throws_like($$select pg_temp.order_action('order_transition','{"status":"cancelled"}')$$,'%Reverta os recebimentos%','cannot cancel active receipts');
select set_config('purchase.account',public.finance_command(gen_random_uuid(),'account_create','{"name":"Purchase QA Bank","kind":"bank"}')#>>'{account,id}',true);
select set_config('purchase.category',public.finance_command(gen_random_uuid(),'category_create','{"name":"Purchase QA Expense","type":"despesa"}')->>'id',true);
select set_config('purchase.payable_payload',(select jsonb_build_object('id',id,'updated_at',updated_at,'account_id',current_setting('purchase.account'),'category_id',current_setting('purchase.category'),'method','boleto')::text from public.purchase_orders where id=current_setting('purchase.order')::uuid),true);
select set_config('purchase.payable_operation',gen_random_uuid()::text,true);
select lives_ok($$select public.purchase_command(current_setting('purchase.payable_operation')::uuid,'payables_generate',current_setting('purchase.payable_payload')::jsonb)$$,'generate canonical payables');
select lives_ok($$select public.purchase_command(current_setting('purchase.payable_operation')::uuid,'payables_generate',current_setting('purchase.payable_payload')::jsonb)$$,'payable generation retry');
select is((select count(*)::int from public.financial_transactions where entry_role='payable'),2,'one obligation per installment');
select is((select count(*)::int from public.financial_transactions where status='pago'),0,'generation is not payment');
select throws_like($$select pg_temp.order_action('payables_generate')$$,'%já geradas%','new operation cannot duplicate obligations');
select is((select sum(amount) from public.financial_transactions where entry_role='payable'),150::numeric,'payables equal total');
select lives_ok($$select public.finance_command(gen_random_uuid(),'payable_pay',(select jsonb_build_object('id',id,'updated_at',updated_at,'date',current_date,'method','pix') from public.financial_transactions where entry_role='payable' order by due_date limit 1))$$,'payment belongs to canonical finance');
select is((select count(*)::int from public.financial_transactions where payable_id is not null and reversal_of is null),1,'payment exactly one movement');
select lives_ok($$select pg_temp.order_action('receipt_reverse',jsonb_build_object('receipt_id',current_setting('purchase.receipt'),'reason','Limpeza QA'))$$,'inverse receipt');
select is((select current_stock from public.products where id='purchase-qa-material'),16::numeric,'inverse movement subtracts quantity');
select is((select count(*)::int from public.purchase_receipts where reversed_at is not null),1,'reversal preserves history');
select lives_ok($$select pg_temp.order_action('receipt_reverse',jsonb_build_object('receipt_id',(select id from public.purchase_receipts where reversed_at is null),'reason','Limpeza QA'))$$,'reverse remaining receipt');
select is((select current_stock from public.products where id='purchase-qa-material'),10::numeric,'stock baseline restored');
select throws_like($$select pg_temp.order_action('order_transition','{"status":"cancelled"}')$$,'%Estorne o pagamento%','paid payable prevents cancel');
select lives_ok($$select public.finance_command(gen_random_uuid(),'payable_reverse',(select jsonb_build_object('id',id,'updated_at',updated_at,'date',current_date) from public.financial_transactions where entry_role='payable' and status='pago'))$$,'finance reverses payment');
select lives_ok($$select pg_temp.order_action('order_transition','{"status":"cancelled"}')$$,'cancel after stock and payment reversal');
select is((select count(*)::int from public.financial_transactions where entry_role='payable' and cancelled_at is not null),2,'cancel canonical pending obligations');
select is((select sum(case when type='receita' then amount else -amount end) from public.financial_transactions where entry_role='movement' and status='pago'),0::numeric,'QA has zero cash balance');
select is((select count(*)::int from public.purchase_receipt_items where stock_movement_id is not null and reversal_movement_id is not null),2,'original and inverse stock references');
select lives_ok($$select public.purchase_source(current_date-1,current_date+1)$$,'authenticated read model');
select throws_like($$select public.purchase_file_access('order','00000000-0000-4000-8000-000000000000',true)$$,'%indisponível%','foreign/missing attachment destination denied');
select throws_like($$select public.purchase_command(gen_random_uuid(),'attachment_add',jsonb_build_object('order_id',current_setting('purchase.order'),'path','other/file.pdf','name','file.pdf','mime','application/pdf','bytes',10))$$,'%Arquivo privado indisponível%','foreign bucket path refused');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'supplier_save',(select to_jsonb(s)||'{"active":false}'::jsonb from public.suppliers s where id=current_setting('purchase.supplier')))$$,'inactivate used supplier preserves history');
select is((select count(*)::int from public.purchase_orders),1,'supplier inactive retains order');
select throws_like($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po())$$,'%fornecedor ativo%','inactive supplier unavailable for new orders');
select throws_like($$delete from public.suppliers where id=current_setting('purchase.supplier')$$,'%permission denied%','used supplier cannot be deleted');
select throws_like($$update public.purchase_orders set total=0$$,'%permission denied%','cannot spoof total by direct write');
select throws_like($$insert into public.purchase_receipts(company_id,order_id,received_date) values(current_setting('purchase.company'),current_setting('purchase.order')::uuid,current_date)$$,'%permission denied%','direct receipt insert denied');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('purchase.company'),'/purchases/approve','{}'),(current_setting('purchase.company'),'/purchases/receive','{}');
set local role authenticated;
select is((public.purchase_source(current_date-1,current_date+1)#>>'{permissions,approve}')::boolean,false,'configured denial includes admin');
select is((public.purchase_source(current_date-1,current_date+1)#>>'{permissions,receive}')::boolean,false,'configured receipt denial');
select set_config('request.jwt.claims','{"sub":"b1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.purchase_orders),0,'cross-tenant orders RLS');
select is((select count(*)::int from public.purchase_receipt_items),0,'cross-tenant cost history RLS');
select is((select count(*)::int from public.supplier_products),0,'cross-tenant vendor reference RLS');
select is((select count(*)::int from public.suppliers),0,'cross-tenant supplier RLS');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save',jsonb_build_object('id',current_setting('purchase.supplier'),'name','Attack'))$$,'%Fornecedor indisponível%','cross-tenant supplier mutation refused');
select throws_like($$select public.purchase_command(gen_random_uuid(),'invoice_save',jsonb_build_object('id',current_setting('purchase.order'),'invoice_number','Attack'))$$,'%Compra indisponível%','cross-tenant purchase mutation refused');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_link',jsonb_build_object('supplier_id',current_setting('purchase.supplier'),'product_id','purchase-qa-material','unit','unidade'))$$,'%ativos%','cross-tenant vendor/product link refused');
reset role;
set local role anon;
select throws_like($$select public.purchase_source(current_date-1,current_date+1)$$,'%permission denied%','anonymous source denied');
select throws_like($$select public.purchase_command(gen_random_uuid(),'supplier_save','{"name":"Attack"}')$$,'%permission denied%','anonymous command denied');
reset role;
select set_config('request.jwt.claims','{"sub":"b1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
delete from public.role_permissions where company_id=current_setting('purchase.company') and path in ('/purchases/approve','/purchases/receive');
set local role authenticated;
select lives_ok($$select public.purchase_command(gen_random_uuid(),'supplier_save',(select to_jsonb(s)||'{"active":true}'::jsonb from public.suppliers s where id=current_setting('purchase.supplier')))$$,'reactivate QA supplier');
select throws_like($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po('{"discount":0.008,"freight":0.004,"expenses":0.004}'))$$,'%duas casas%','monetary operands individually validated before rounding');
select lives_ok($$select public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po(jsonb_build_object('discount',0.50,'freight',0,'expenses',0,'items',(select jsonb_agg(jsonb_build_object('description','Cent item '||g,'unit','unidade','quantity',1,'unit_price',0.01)) from generate_series(1,100) g),'installments',jsonb_build_array(jsonb_build_object('due_date',current_date,'amount',0.50)))))$$,'100 small lines allocate safely');
select is((select sum(acquisition_total) from public.purchase_order_items where order_id=(select id from public.purchase_orders order by number desc limit 1)),0.50::numeric,'cumulative cent allocation reconciles');
select is((select min(acquisition_total)>=0 from public.purchase_order_items),true,'no negative allocation');
select set_config('purchase.order',(public.purchase_command(gen_random_uuid(),'order_save',pg_temp.po())->>'id'),true);
select set_config('purchase.confirm_operation',gen_random_uuid()::text,true);
select set_config('purchase.confirm_payload',(select jsonb_build_object('id',id,'updated_at',updated_at,'status','confirmed')::text from public.purchase_orders where id=current_setting('purchase.order')::uuid),true);
select lives_ok($$select public.purchase_command(current_setting('purchase.confirm_operation')::uuid,'order_transition',current_setting('purchase.confirm_payload')::jsonb)$$,'new purchase confirmed for permission tests');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('purchase.company'),'/stock','{}'),(current_setting('purchase.company'),'/financial','{}'),(current_setting('purchase.company'),'/purchases/approve','{}') on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select is((public.purchase_source(current_date,current_date)#>>'{permissions,receive}')::boolean,false,'stock configured denial beats admin default');
select throws_like($$select pg_temp.order_action('receive',jsonb_build_object('received_date',current_date,'items',jsonb_build_array(jsonb_build_object('item_id',(select id from public.purchase_order_items where order_id=current_setting('purchase.order')::uuid order by position limit 1),'quantity',1))))$$,'%Sem permissão%','admin cannot receive when Stock explicitly denied');
select throws_like($$select pg_temp.order_action('receipt_reverse',jsonb_build_object('receipt_id',current_setting('purchase.receipt'),'reason','Attack'))$$,'%Sem permissão%','admin cannot reverse when Stock explicitly denied');
select throws_like($$select public.purchase_command(current_setting('purchase.operation')::uuid,'receive',current_setting('purchase.receipt_payload')::jsonb)$$,'%Sem permissão%','receipt replay reauthorizes Stock');
select throws_like($$select public.purchase_command(current_setting('purchase.payable_operation')::uuid,'payables_generate',current_setting('purchase.payable_payload')::jsonb)$$,'%exigem acesso ao Financeiro%','payable replay reauthorizes Finance');
select throws_like($$select public.purchase_command(current_setting('purchase.confirm_operation')::uuid,'order_transition',current_setting('purchase.confirm_payload')::jsonb)$$,'%Sem permissão%','confirmation replay reauthorizes approval');
select throws_like($$select pg_temp.order_action('payables_generate')$$,'%exigem acesso ao Financeiro%','financial configured denial enforced');
reset role;
delete from public.role_permissions where company_id=current_setting('purchase.company') and path in ('/stock','/financial','/purchases/approve');
insert into storage.objects(bucket_id,name,metadata) values('purchase-documents',current_setting('purchase.company')||'/supplier/'||current_setting('purchase.supplier')||'/b1100000-0000-4000-8000-000000000099.pdf','{"size":10,"mimetype":"application/pdf"}');
set local role authenticated;
select lives_ok($$select public.purchase_command(gen_random_uuid(),'attachment_add',jsonb_build_object('supplier_id',current_setting('purchase.supplier'),'path',current_setting('purchase.company')||'/supplier/'||current_setting('purchase.supplier')||'/b1100000-0000-4000-8000-000000000099.pdf','name','QA.pdf','mime','application/pdf','bytes',10))$$,'register private supplier object in correct scope');
select is((select count(*)::int from storage.objects where bucket_id='purchase-documents'),1,'authorized private object visible');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('purchase.company'),'/suppliers','{}');
set local role authenticated;
select is((select count(*)::int from storage.objects where bucket_id='purchase-documents'),0,'supplier-denied actor cannot read supplier private file');
select throws_like($$select public.purchase_command(gen_random_uuid(),'attachment_add',jsonb_build_object('order_id',current_setting('purchase.order'),'path',current_setting('purchase.company')||'/supplier/'||current_setting('purchase.supplier')||'/b1100000-0000-4000-8000-000000000099.pdf','name','QA.pdf','mime','application/pdf','bytes',10))$$,'%Arquivo privado indisponível%','cannot re-scope supplier file to readable purchase');
select ok(not(public.purchase_source(current_date,current_date)#>'{suppliers,0}'?'contacts'),'Purchases-only source redacts supplier contact registry');
select is((select count(*)::int from public.suppliers),0,'direct REST/SELECT supplier registry obeys configured module denial');
select set_config('request.jwt.claims','{"sub":"b1100000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_like($$select public.purchase_command(current_setting('purchase.operation')::uuid,'receive',current_setting('purchase.receipt_payload')::jsonb)$$,'%outro usuário%','same-tenant peer cannot reuse another actor receipt');
reset role;
select * from finish();
rollback;
